#!/usr/bin/env python3
"""PRIO1 analysis (planned/PRIO1_PREREG.md). FCFS references: INTENT2 (A2 N2), GAP1 (G1 V135)."""
import json, glob
rd = lambda p: [json.loads(l) for f in glob.glob(p) for l in open(f) if l.strip()]
NEW = rd('out/prio1/*.jsonl')
REF = [dict(r, rule='FCFS') for r in rd('out/intent2/*.jsonl') if r['part'] == 'c' and r['heights'] == 'A2' and r['vol'] == 'N2'] + [dict(r, rule='FCFS') for r in rd('out/gap1/*.jsonl') if r['part'] == 'c' and r['heights'] == 'G1' and r['vol'] == 'V135']
R = NEW + REF; M, CONF, OPS, RULES = ('houston', 'dfw'), (('A2', 'N2'), ('G1', 'V135')), ('wing', 'zipline', 'amazon'), ('FCFS', 'ROT', 'SHORT', 'FAIR')
def rows(m, c, rule): return [r for r in R if r['metro'] == m and r['heights'] == c[0] and r['vol'] == c[1] and r['rule'] == rule and r['seed'] <= 5]
def held(m, c, rule, op='all'):
    x = [r['cost'][op] for r in rows(m, c, rule) if op in r['cost']]; n = sum(b['n'] for b in x); return sum(b['delayed'] + b['cancelled'] for b in x) / n if n else float('nan')
def wait_h(m, c, rule):
    x = [r['cost']['all'] for r in rows(m, c, rule)]; return sum(b['sumD'] + 1200 * b['cancelled'] for b in x) / 3600
def meanw(m, c, rule, op):
    x = [r['cost'][op] for r in rows(m, c, rule) if op in r['cost']]; d = sum(b['delayed'] for b in x); return sum(b['sumD'] for b in x) / d / 60 if d else 0
def spread(m, c, rule): v = [held(m, c, rule, op) for op in OPS]; return max(v) - min(v)
P = []
def chk(n, ok, t): P.append((n, ok, t)); print('PASS' if ok else 'FAIL', n, t)
EV = [(m, c) for m in M for c in CONF]; lab = lambda m, c: f'{m} {c[0]}/{c[1]}'
chk('R1', all(wait_h(m, c, 'SHORT') < wait_h(m, c, 'FCFS') for m, c in EV), '; '.join(f'{lab(m, c)} SHORT {wait_h(m, c, "SHORT"):.0f} h vs FCFS {wait_h(m, c, "FCFS"):.0f} h' for m, c in EV))
chk('R2', all(held(m, c, 'SHORT', 'amazon') > held(m, c, 'FCFS', 'amazon') for m, c in EV), '; '.join(f'{lab(m, c)} Amazon SHORT {100 * held(m, c, "SHORT", "amazon"):.1f} vs FCFS {100 * held(m, c, "FCFS", "amazon"):.1f} %' for m, c in EV))
chk('R3', all(abs(held(m, c, 'ROT') / held(m, c, 'FCFS') - 1) < 0.10 for m, c in EV), '; '.join(f'{lab(m, c)} ROT {100 * held(m, c, "ROT"):.1f} vs FCFS {100 * held(m, c, "FCFS"):.1f} %' for m, c in EV))
chk('R4', all(held(m, CONF[0], 'FCFS', 'amazon') - held(m, CONF[0], 'FAIR', 'amazon') >= 0.10 for m in M), '; '.join(f'{m} A2/N2 Amazon FAIR {100 * held(m, CONF[0], "FAIR", "amazon"):.1f} vs FCFS {100 * held(m, CONF[0], "FCFS", "amazon"):.1f} %' for m in M))
chk('R5', all(spread(m, c, 'FAIR') < spread(m, c, 'FCFS') for m, c in EV), '; '.join(f'{lab(m, c)} spread FAIR {100 * spread(m, c, "FAIR"):.1f} vs FCFS {100 * spread(m, c, "FCFS"):.1f} pts' for m, c in EV))
npass = sum(1 for _, ok, _ in P if ok)
L = ['# PRIO1 results table (generated by planned/prio1_analyze.py)', '', f'{npass} of {len(P)} predictions passed. New rows: {len(NEW)}.', ''] + [f'- {"PASS" if ok else "FAIL"} {n}: {t}' for n, ok, t in P]
L += ['', '| Metro | Setting | Rule | Held | Wing | Zipline | Amazon | Spread (pts) | Total waiting (h, cancel = 20 min) | Mean wait Wing / Zipline / Amazon (min) |', '|---|---|---|---|---|---|---|---|---|---|']
for m in M:
    for c in CONF:
        for r in RULES: L.append(f'| {m} | {c[0]}/{c[1]} | {r} | {100 * held(m, c, r):.1f} % | ' + ' | '.join(f'{100 * held(m, c, r, op):.1f} %' for op in OPS) + f' | {100 * spread(m, c, r):.1f} | {wait_h(m, c, r):.0f} | ' + ' / '.join(f'{meanw(m, c, r, op):.1f}' for op in OPS) + ' |')
open('planned/prio1_results_table.md', 'w').write('\n'.join(L) + '\n'); print(f'{npass} of {len(P)} passed')
